import numpy as np

def log_softmax(z):
    m = z.max()
    return z - m - np.log(np.exp(z - m).sum())

def ce(z, target):                      # target: 확률 분포(원-핫 또는 스무딩)
    return -(target * log_softmax(z)).sum()

z = np.array([2.0, 1.0, 0.1])
onehot = np.array([1.0, 0, 0])
for eps in (0.0, 0.05, 0.1):
    k = len(z)
    target = (1 - eps) * onehot + eps / k   # 일반형 라벨 스무딩
    print(eps, target.round(3), round(ce(z, target), 3))

# 원-핫 목표는 점수 차이를 끝없이 키우게 한다
for gap in (2, 5, 10, 20):
    zz = np.array([gap, 0.0, 0.0])
    print(gap, round(ce(zz, onehot), 5), round(ce(zz, 0.9 * onehot + 0.1 / 3), 3))
